import type { PhotoPileOptions } from './photo-pile.motion.js';

import type { ImgHTMLAttributes } from 'vue';

export interface PhotoPilePhoto {
    /** Unique, stable key for this photo. */
    id: string;
    src: string;
    alt: string;
    x?: number;
    y?: number;
    rotation?: number;
    imageProps?: Omit<ImgHTMLAttributes, 'src' | 'alt' | 'draggable'>;
}

export interface PhotoPileProps extends PhotoPileOptions {
    photos: readonly PhotoPilePhoto[];
    /** Multiplies default and authored x/y offsets. @default 1 */
    spread?: number;
}

/** Vue component refs expose the root DOM element, null when presence removes it. */
export interface KidaElement {
    element: HTMLElement | null;
}

[data-kida-photo-pile] {
  --kida-photo-width: clamp(9rem, 42%, 13.5rem);
  --kida-photo-radius: 0.55rem;
  --kida-photo-frame: #fffafb;
  --kida-photo-shadow: 0 0.8rem 2rem rgb(50 30 42 / 16%);

  position: relative;
  display: block;
  min-inline-size: 0;
  width: min(100%, 36rem);
  min-height: 22rem;
  margin: 0;
  padding: 0;
  border: 0;
  isolation: isolate;
}

/* Chromium does not reliably use a fieldset itself as the containing block for absolutely
   positioned children. A normal-flow stage keeps every card anchored to the pile wherever the
   fieldset appears on the page. */
[data-kida-photo-stage] {
  position: relative;
  display: block;
  /* Fill explicitly sized previews as well as the pile's default minimum height. */
  height: 100%;
  min-height: inherit;
}

[data-kida-photo-item] {
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--kida-photo-width);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--kida-photo-radius);
  background: transparent;
  /* Custom photo cards must not use WebKit's pixel-snapped native button appearance. */
  appearance: none;
  cursor: grab;
  touch-action: none;
  transform: translate(-50%, -50%) translate(var(--kida-photo-x), var(--kida-photo-y))
    rotate(var(--kida-photo-rotation));
}

[data-kida-photo-item][data-dragging] {
  cursor: grabbing;
}

[data-kida-photo-item]:focus-visible {
  outline: 3px solid var(--kida-photo-focus, #6d52a8);
  outline-offset: 5px;
}

[data-kida-photo-card] {
  display: block;
  padding: 0.45rem 0.45rem 1.8rem;
  border: 1px solid rgb(55 35 48 / 12%);
  border-radius: var(--kida-photo-radius);
  background: var(--kida-photo-frame);
  box-shadow: var(--kida-photo-shadow);
  user-select: none;
}

[data-kida-photo-card] img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 5;
  border-radius: calc(var(--kida-photo-radius) - 0.2rem);
  object-fit: cover;
  pointer-events: none;
}

@media (max-width: 32rem) {
  [data-kida-photo-pile] {
    --kida-photo-width: min(48%, 10.5rem);

    min-height: 18rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-kida-photo-card] {
    /* biome-ignore lint/complexity/noImportantStyles: stops an in-flight inline transform */
    transform: none !important;
  }
}

import { animate } from 'motion'
import { prefersReducedMotion } from './reduced-motion.motion.js'

export interface PhotoPileOptions {
  /** Scale applied while a photo is being dragged. @default 1.035 */
  dragScale?: number
  /** Degrees of responsive tilt per horizontal CSS pixel. @default 0.025 */
  tilt?: number
}

const DEFAULTS = { dragScale: 1.035, tilt: 0.025 } as const
const IDENTITY = 'translate3d(0px, 0px, 0) rotate(0deg) scale(1)'

/**
 * Adds direct pointer dragging and a spring return to every photo card in a pile.
 * The positioned item stays still; only its inner card moves, so authored layout transforms
 * never compete with the drag transform.
 */
export function photoPile(root: HTMLElement, options: PhotoPileOptions = {}): () => void {
  const { dragScale = DEFAULTS.dragScale, tilt = DEFAULTS.tilt } = options
  const reduced = prefersReducedMotion()
  const items = [...root.querySelectorAll<HTMLElement>('[data-kida-photo-item]')]
  const cleanups: Array<() => void> = []
  const originalZ = new Map(items.map((item) => [item, item.style.zIndex]))
  let topLayer = items.length

  const activate = (item: HTMLElement) => {
    topLayer += 1
    item.style.zIndex = String(topLayer)
  }

  for (const item of items) {
    const card = item.querySelector<HTMLElement>('[data-kida-photo-card]')
    if (!card) continue

    let pointerId: number | undefined
    let originX = 0
    let originY = 0
    let x = 0
    let y = 0
    let frame = 0
    let settleFrame = 0
    let controls: ReturnType<typeof animate> | undefined

    const transform = () =>
      `translate3d(${x}px, ${y}px, 0) rotate(${x * tilt}deg) scale(${dragScale})`

    const paint = () => {
      frame = 0
      card.style.transform = transform()
    }

    const settle = () => {
      controls?.cancel()
      controls = undefined
      card.style.transform = 'none'
      card.style.willChange = 'auto'
      delete item.dataset.dragging
    }

    const onPointerDown = (event: PointerEvent) => {
      if (pointerId !== undefined || (event.pointerType === 'mouse' && event.button !== 0)) return
      if (settleFrame) {
        cancelAnimationFrame(settleFrame)
        settleFrame = 0
      }
      controls?.cancel()
      pointerId = event.pointerId
      originX = event.clientX
      originY = event.clientY
      x = 0
      y = 0
      activate(item)
      item.dataset.dragging = ''
      card.style.willChange = 'transform'
      card.style.transform = IDENTITY
      try {
        item.setPointerCapture(pointerId)
      } catch {
        // Synthetic pointer events and older browsers may not expose capture; window listeners
        // below still keep the gesture alive.
      }
    }

    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerId !== pointerId) return
      x = event.clientX - originX
      y = event.clientY - originY
      if (!frame) frame = requestAnimationFrame(paint)
    }

    const onPointerEnd = (event: PointerEvent) => {
      if (event.pointerId !== pointerId) return
      pointerId = undefined
      if (frame) {
        cancelAnimationFrame(frame)
        frame = 0
        card.style.transform = transform()
      }
      try {
        if (item.hasPointerCapture(event.pointerId)) item.releasePointerCapture(event.pointerId)
      } catch {
        // See the capture fallback above.
      }

      if (reduced) {
        settle()
        return
      }

      const from = transform()
      controls = animate(
        card,
        { transform: [from, IDENTITY] },
        {
          type: 'spring',
          stiffness: 420,
          damping: 30,
          mass: 0.7,
          // Motion commits the final keyframe after calling onComplete. Clear that committed
          // identity transform on the following frame so the card truly returns to authored CSS.
          onComplete: () => {
            settleFrame = requestAnimationFrame(() => {
              settleFrame = 0
              settle()
            })
          },
        },
      )
    }

    const onFocus = () => activate(item)
    item.addEventListener('pointerdown', onPointerDown)
    window.addEventListener('pointermove', onPointerMove)
    window.addEventListener('pointerup', onPointerEnd)
    window.addEventListener('pointercancel', onPointerEnd)
    item.addEventListener('focusin', onFocus)

    cleanups.push(() => {
      item.removeEventListener('pointerdown', onPointerDown)
      window.removeEventListener('pointermove', onPointerMove)
      window.removeEventListener('pointerup', onPointerEnd)
      window.removeEventListener('pointercancel', onPointerEnd)
      item.removeEventListener('focusin', onFocus)
      if (frame) cancelAnimationFrame(frame)
      if (settleFrame) cancelAnimationFrame(settleFrame)
      settle()
    })
  }

  return () => {
    for (const cleanup of cleanups) cleanup()
    for (const item of items) item.style.zIndex = originalZ.get(item) ?? ''
  }
}

const QUERY = '(prefers-reduced-motion: reduce)'

/**
 * Whether the user has asked for reduced motion.
 *
 * SSR-safe: returns `false` when there is no `window`, matching the CSS default
 * (the `prefers-reduced-motion` media query in `@kida-ui/styles` is the real guard;
 * this is for the JS-driven paths that CSS cannot express).
 */
export function prefersReducedMotion(): boolean {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return false
  return window.matchMedia(QUERY).matches
}

/**
 * Subscribe to changes of the reduced-motion preference.
 * Returns an unsubscribe function. No-op (and immediately unsubscribable) on the server.
 */
export function watchReducedMotion(onChange: (reduced: boolean) => void): () => void {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return () => {}

  const list = window.matchMedia(QUERY)
  const handler = (event: MediaQueryListEvent) => onChange(event.matches)
  list.addEventListener('change', handler)
  return () => list.removeEventListener('change', handler)
}
